declarations.type:
∀ {n : Nat} {u : Real} {rnd : Real → Real} {A : CholeskySolve.Mat n} {b : CholeskySolve.Vec n} {R : CholeskySolve.Mat n}
  {y x : CholeskySolve.Vec n},
  CholeskySolve.SolveRun u rnd A b R y x → CholeskySolve.ForwardRun u rnd (Matrix.transpose.{0, 0, 0} R) b y

declarations.body:
fun {n} A R L U =>
  HAdd.hAdd.{0, 0, 0}
    (HAdd.hAdd.{0, 0, 0}
      (HAdd.hAdd.{0, 0, 0} (CholeskySolve.factorResidual A R) (HMul.hMul.{0, 0, 0} (Matrix.transpose.{0, 0, 0} R) U))
      (HMul.hMul.{0, 0, 0} L R))
    (HMul.hMul.{0, 0, 0} L U)
